import{X as e,Z as t,t as n,ut as r}from"./chunks/framework.es-12sf8.js";var i=JSON.parse(`{"title":"Request Abstraction","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/request.md","filePath":"en/deep-dive/request.md","lastUpdated":1787300168000}`),a={name:`deep-dive/request.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="request-abstraction" tabindex="-1">Request Abstraction <a class="header-anchor" href="#request-abstraction" aria-label="Permalink to “Request Abstraction”">​</a></h1><p>Sync Engine exposes two typed request functions:</p><ul><li><code>Request</code> for remote HTTP operations</li><li><code>VaultRequest</code> for local Obsidian vault operations</li></ul><p>Both are function objects returning promises. They provide a small, middleware-friendly boundary between file-system implementations and their underlying platform APIs.</p><h2 id="request" tabindex="-1">Request <a class="header-anchor" href="#request" aria-label="Permalink to “Request”">​</a></h2><p><code>Request</code> is defined in <code>packages/plugin/src/modules/Registrar.ts</code>:</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Request</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">params</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> RequestParam</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Promise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">RequestResponse</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;;</span></span></code></pre></div><p><code>RequestParam</code> follows Obsidian&#39;s <code>RequestUrlParam</code>, except <code>body</code> uses the project&#39;s <code>Binary</code> (<code>Uint8Array</code>) instead of <code>ArrayBuffer</code> in Obsidian raw API. A string argument is treated as a <code>GET</code> toward this URL.</p><p><code>RequestResponse</code> is an exported SDK type describing the response returned by <code>Request</code>.</p><h3 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to “Implementation”">​</a></h3><p>The base implementation:</p><ol><li>Converts a <code>Uint8Array</code> body to an <code>ArrayBuffer</code>.</li><li>Calls Obsidian <code>requestUrl()</code>.</li><li>Wraps the result as: <ul><li><code>status</code>: HTTP status code</li><li><code>headers</code>: response headers</li><li><code>text()</code>: response text</li><li><code>json()</code>: parsed JSON</li><li><code>bytes()</code>: response <code>ArrayBuffer</code> converted to <code>Binary</code></li></ul></li></ol><p>Remote file-system modules receive <code>getRequest()</code> in context, not the base function directly. <code>Registrar</code> applies registered remote request middleware in priority order before returning it. Each remote FS operation therefore uses the same abstraction for authentication, headers, retries, rate limiting, and cancellation.</p><h3 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to “Limitations”">​</a></h3><ul><li>Obsidian <code>requestUrl()</code> accepts only a complete string or <code>ArrayBuffer</code> body. <code>Request</code> cannot upload a <code>ReadableStream</code>.</li><li><code>requestUrl()</code> does not expose a response body stream through this abstraction. <code>bytes()</code> materializes the complete response.</li><li>Streaming remote reads must be implemented above <code>Request</code>, normally with multiple ranged requests. Streaming writes must either buffer the input or use a backend-specific chunked-upload protocol.</li><li>Request errors are normally thrown by <code>requestUrl()</code> for HTTP status <code>400</code> and above. Retry behavior belongs to request middleware, not this base implementation.</li></ul><h2 id="vault-request" tabindex="-1">Vault Request <a class="header-anchor" href="#vault-request" aria-label="Permalink to “Vault Request”">​</a></h2><p><code>VaultRequest</code> is the local counterpart used by <code>VaultFs</code>, uses Obsidian vault cache smartly to improve performance. It is a discriminated operation function:</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> VaultRequest</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> extends</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> VaultRequestParam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;(</span></span>
<span class="line"><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">  params</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Promise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">VaultRequestResponseMap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;method&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]&gt;;</span></span></code></pre></div><p>Supported methods are <code>GET</code>, <code>GET_STREAM</code>, <code>PUT</code>, <code>APPEND</code>, <code>DELETE</code>, <code>MOVE</code>, <code>MKDIR</code>, <code>EXISTS</code>, <code>STAT</code>, and <code>LIST</code>. The method determines both required parameters and response type.</p><p><code>createVaultRequest(app)</code> captures <code>app.vault</code>, its <code>DataAdapter</code>, and <code>app.workspace</code>. <code>Registrar</code> applies local request middleware before injecting the function into <code>VaultFs</code>.</p><h3 id="path-conversion" tabindex="-1">Path conversion <a class="header-anchor" href="#path-conversion" aria-label="Permalink to “Path conversion”">​</a></h3><p>The request key uses the <a href="./file-system#unified-key-schema">unified file-system key schema</a>.</p><p>Before calling the adapter, <code>VaultRequest</code> removes a trailing slash from every non-root path because Obsidian paths do not use folder slashes. <code>LIST</code> converts returned folder paths back to the unified form.</p><h3 id="operation-mapping" tabindex="-1">Operation mapping <a class="header-anchor" href="#operation-mapping" aria-label="Permalink to “Operation mapping”">​</a></h3><ul><li><code>GET</code>: <code>adapter.readBinary()</code>, converted to <code>Binary</code>.</li><li><code>GET_STREAM</code>: fetches <code>adapter.getResourcePath(path)</code> and returns <code>response.body</code>; throws when no body is available. File read streaming is achieved in this way.</li><li><code>PUT</code>: <code>adapter.writeBinary()</code>, converting <code>Binary</code> to <code>ArrayBuffer</code> and forwarding optional <code>mtime</code>/<code>ctime</code> headers.</li><li><code>APPEND</code>: <code>adapter.appendBinary()</code> with the same conversion and headers.</li><li><code>DELETE</code>: calls <code>adapter.remove()</code>, <code>adapter.trashLocal()</code>, <code>adapter.trashSystem()</code> according to user trash options.</li><li><code>MOVE</code>: <code>adapter.rename()</code> to the normalized destination path.</li><li><code>MKDIR</code>: calls <code>adapter.mkdir()</code>. Creating <code>/</code> is a no-op.</li><li><code>EXISTS</code>: checks <code>vault.getAbstractFileByPath()</code> first, then fallback to <code>adapter.exists(path, true)</code>.</li><li><code>STAT</code>: returns an stat object typed in Obsidian <code>Stat</code>; with <code>cached</code> enabled, uses cached <code>TFile</code>/<code>TFolder</code> objects when <code>workspace.layoutReady</code>, otherwise falls back to <code>adapter.stat()</code>.</li><li><code>LIST</code>: with <code>cached</code> enabled, uses cached <code>TFolder.children</code> when the layout is ready and the key is not <code>/</code>; otherwise uses <code>adapter.list()</code>. Folder results are normalized with trailing slashes.</li></ul><h2 id="boundary" tabindex="-1">Boundary <a class="header-anchor" href="#boundary" aria-label="Permalink to “Boundary”">​</a></h2><p><code>Request</code> abstracts HTTP transport; <code>VaultRequest</code> abstracts vault adapter access. Neither performs file-system policy such as retries, memory control, path flattening, or cancellation. Those behaviors are supplied by the corresponding middleware and FS wrappers.</p>`,27)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};